local K=KeijinUI
-- Font choice. FontCatalog.lua (generated by development/keijinui/prepare_fonts.py) lists each font with the languages
-- whose characters it draws completely and a size factor. The choice is stored in K.DB().fontFace; Friz Quadrata is the default.
-- A font that lacks characters of the interface language is replaced by K.LangFont (KeijinCJK.ttf for the wide languages).
local DEFAULT="friz"
local FRIZ="Fonts\\FRIZQT__.TTF"
local catalog=KeijinFontCatalog or {}
local byKey={}
K.fontChoices={}
for _,entry in ipairs(catalog) do
    byKey[entry.key]=entry
    table.insert(K.fontChoices,{entry.key,entry.name})
end
local function Covers(entry,lang)
    for _,code in ipairs(entry.langs) do if code==lang then return true end end
    return false
end
-- The stored key; old values (friz, arial) stay valid, unknown ones mean Friz Quadrata.
function K.FontChoice()
    local key=K.DB().fontFace
    if key and byKey[key] then return key end
    return DEFAULT
end
-- Path and size factor of the font used for a language, and true when the chosen font had to be replaced.
function K.ResolveFont(lang,key)
    lang=lang or K.lang
    local entry=byKey[key or K.FontChoice()]
    if entry and Covers(entry,lang) then return entry.path,entry.factor,false end
    local path=K.LangFont(lang,FRIZ)
    return path,1,(entry==nil or entry.path~=path)
end
function K.FontSubstituted()
    local _,_,substituted=K.ResolveFont(K.lang)
    return substituted
end
-- For the interface: {key,name,covers the current language} in catalog order.
function K.FontChoices()
    local out={}
    for _,entry in ipairs(catalog) do table.insert(out,{entry.key,entry.name,Covers(entry,K.lang)}) end
    return out
end
function K.FontName(key) return byKey[key] and byKey[key].name or tostring(key) end
local nativeFonts={}
-- Sets every registered font string again from its unscaled size (K.fontBase or the registered size), so repeated
-- changes never add up. Tooltip and chat fonts change only in the languages that were switched before (wide fonts).
function K.ApplyFont()
    local path,factor=K.ResolveFont(K.lang)
    K.font=path; K.fontFactor=factor
    for _,v in ipairs(K.fontStrings or {}) do
        local fs,flags=v[1]
        if fs.GetFont then
            local _,_,f=fs:GetFont()
            flags=f
        end
        local fixed=K.fontOverrides[fs]
        local size=K.fontBase[fs] or v[2]
        fs:SetFont(fixed or path,fixed and size or K.FontSize(size),flags or "OUTLINE")
    end
    -- Restore native font paths after leaving a language that needed our fallback.
    -- Keep the current chat/tooltip size, including changes made by the player.
    local function Native(fs,defaultSize,defaultFlags)
        if fs and fs.GetFont and fs.SetFont then
            local old,size,flags=fs:GetFont()
            if K.NeedsWideFont(K.lang) then
                if not nativeFonts[fs] then nativeFonts[fs]=old or FRIZ end
                -- Chat and game tooltips may contain other players' scripts,
                -- not just characters from the chosen interface language.
                fs:SetFont(K.WideFont,size or defaultSize,flags or defaultFlags)
            elseif nativeFonts[fs] then
                fs:SetFont(nativeFonts[fs],size or defaultSize,flags or defaultFlags)
                nativeFonts[fs]=nil
            end
        end
    end
    for _,name in ipairs({"GameTooltipText","GameTooltipHeaderText","GameTooltipTextSmall","ChatFontNormal"}) do Native(getglobal(name),11,"") end
    for i=1,30 do
        for _,side in ipairs({"Left","Right"}) do Native(getglobal("GameTooltipText"..side..i),11,"") end
    end
    for i=1,NUM_CHAT_WINDOWS or 7 do Native(getglobal("ChatFrame"..i),14,"") end
end
-- Stores the choice and applies it at once, without a reload.
function K.SetFontChoice(key)
    if not byKey[key] then return false end
    K.DB().fontFace=key
    K.ApplyFont()
    return true
end
K.On("ADDON_LOADED",function(_,name) if name=="KeijinUI" then K.ApplyFont() end end)
K.OnLang(function() K.ApplyFont() end)
if K.NeedsWideFont(K.lang) then K.ApplyFont() end
